package dev.hoi.client.map.commander;

import com.mojang.blaze3d.platform.InputConstants;
import dev.hoi.client.ClientCampaignHud;
import dev.hoi.client.screen.map.MapCursor;
import dev.hoi.client.ui.UiCommandLabels;
import dev.hoi.protocol.commander.CommanderHudPayloads.*;
import dev.hoi.protocol.commander.*;
import dev.hoi.protocol.hud.*;
import dev.hoi.protocol.menu.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.input.MouseButtonEvent;
import net.minecraft.client.input.MouseButtonInfo;
import java.util.*;

public final class CommanderAirBasePanelsTest {
    private static Member wing(String id,String base,int occupied,int capacity){boolean carrier=id.equals("c");return new Member(id,id,"대기 중","unit_hud/air_fighter","",1,new Open(Mode.AIR_MISSION,id),"",null,Map.of(),"같은 기지명","HOLD",new MemberData("","",100,null,null,true,new AirData("","","ANY",new AirBase(base,occupied-100,occupied,capacity,"KOR"),new AirWingDetails(100,"BOTH","",carrier,"대기 중")),null,null,null,null,null,null,null,null,null,null,null,"","",null,null,"",carrier?Map.of("picture","picture-"+id,"carrier","carrier-"+id):Map.of("picture","picture-"+id)));}
    public static void run(ClientGameTestContext game,MenuView menu){int previous=game.computeOnClient(client->client.options.guiScale().get());try{for(int[] size:List.of(new int[]{2560,1440,2},new int[]{1280,720,2},new int[]{1920,1080,3},new int[]{2560,1440,1})){
        var requests=new ArrayList<Open>();var view=new View[1];game.getInput().resizeWindow(size[0],size[1]);game.runOnClient(client->{client.options.guiScale().set(size[2]);ClientCampaignHud.accept(HudPayloads.State.of("KOR",menu.hud()));CommanderHud.reset();CommanderUnitHud.reset();CommanderHud.requestObserver=requests::add;view[0]=new View("KOR",client.level.dimension().identifier().toString(),Mode.AIR,List.of(),List.of(wing("a","base-a",250,400),wing("b","base-b",500,400)));CommanderHud.accept(view[0]);CommanderPanels.showWings(List.of("a","b"));});game.setScreen(MapCursor::new);game.waitTicks(3);
        game.runOnClient(client->{var closes=CommanderPanels.hits().stream().filter(h->h.icon().equals("air_base_close")).sorted(Comparator.comparingInt(CommanderPanels.Hit::y)).toList();if(client.getWindow().getGuiScale()!=size[2])throw new AssertionError("Requested air detail GUI scale must be active");for(var hit:CommanderPanels.hits())if(hit.x()<0||hit.y()<0||hit.x()+hit.w()>client.getWindow().getGuiScaledWidth()||hit.y()+hit.h()>client.getWindow().getGuiScaledHeight())throw new AssertionError("Air detail input escaped viewport: "+hit.icon());if(closes.size()!=2)throw new AssertionError("Different stable bases with the same label must have independent headers");var tips=CommanderPanels.hits().stream().map(CommanderPanels.Hit::tip).toList();if(tips.stream().noneMatch(t->t.contains("250")&&t.contains("400"))||tips.stream().noneMatch(t->t.contains("500")&&t.contains("400")))throw new AssertionError("Headers must show full authoritative base counts, not selected-wing totals");var cas=mission("AIRWING_MISSION_TYPE_CAS");var intercept=mission("AIRWING_MISSION_TYPE_INTERCEPTION");if(cas.x()>=intercept.x())throw new AssertionError("Native CAS then interception order required");click(cas);if(requests.size()!=1||!requests.getFirst().selection().equals(List.of("mission/CLOSE_AIR_SUPPORT","a","b")))throw new AssertionError("CAS icon must issue CAS for precisely selected wings");requests.clear();var create=CommanderPanels.hits().stream().filter(h->h.tip().equals(UiCommandLabels.text("AIRWING_NEW","신규 비행단 창설"))).sorted(Comparator.comparingInt(CommanderPanels.Hit::y)).findFirst().orElseThrow();click(create);if(requests.size()!=1||!requests.getFirst().selection().equals(List.of("action/CREATE","base/base-a")))throw new AssertionError("Base create button must bind the exact stable base");requests.clear();});listPanel(game,game.takeScreenshot("hoi-air-independent-base-capacity-"+size[0]+"x"+size[1]+"-gui"+size[2]));baseTooltip(game,size,requests);
        game.runOnClient(client->{var close=CommanderPanels.hits().stream().filter(h->h.icon().equals("air_base_close")).min(Comparator.comparingInt(CommanderPanels.Hit::y)).orElseThrow();click(close);if(!CommanderPanels.commandSelection().equals(List.of("air/b"))||!requests.isEmpty())throw new AssertionError("Closing one base must only deselect its own wings");CommanderHud.accept(view[0]);});game.waitTicks(2);game.runOnClient(client->{if(!CommanderPanels.commandSelection().equals(List.of("air/b"))||CommanderPanels.hits().stream().filter(h->h.icon().equals("air_base_close")).count()!=1)throw new AssertionError("Refresh must preserve scoped base deselection");if(view[0].wings().stream().anyMatch(w->!w.mission().equals("HOLD")))throw new AssertionError("Base close changed mission state");});game.takeScreenshot("hoi-air-base-deselection-preserves-other-base-"+size[0]+"x"+size[1]+"-gui"+size[2]);wingControls(game,size,requests);
    }realWingList(game,menu);CommanderAirWingWindowTest.run(game,menu);}finally{game.runOnClient(client->{client.options.guiScale().set(previous);CommanderHud.requestObserver=null;CommanderHud.reset();CommanderUnitHud.reset();});}}
    private static void realWingList(ClientGameTestContext game,MenuView menu){
        View source;try{source=new Snapshot(java.nio.file.Files.readString(java.nio.file.Path.of(Objects.requireNonNull(System.getenv("HOI_COMMANDER_PREVIEW")),"kor-command-panel-air.json"))).view();}catch(java.io.IOException error){throw new java.io.UncheckedIOException(error);}
        var last=source.wings().stream().sorted(Comparator.comparing(CommanderAirBases::identity).thenComparing(Member::id)).toList().getLast();
        game.getInput().resizeWindow(1280,720);
        game.runOnClient(client->{client.options.guiScale().set(2);ClientCampaignHud.accept(HudPayloads.State.of("KOR",menu.hud()));CommanderHud.reset();CommanderUnitHud.reset();CommanderHud.accept(new View(source.country(),client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings(),source.running(),source.theaters(),source.armyTheaters()));CommanderPanels.showWings(source.wings().stream().map(Member::id).toList());});
        game.setScreen(MapCursor::new);game.waitTicks(3);
        game.runOnClient(client->{var hits=CommanderPanels.hits();if(hits.stream().anyMatch(h->h.tip().equals("\uc774\uc804")||h.tip().equals("\ub2e4\uc74c")))throw new AssertionError("Air wing list must scroll without page buttons");if(hits.stream().anyMatch(h->h.tip().startsWith("\u00a7e"+last.name()+"\u00a7r")))throw new AssertionError("Real KOR wing list must overflow at 1280x720");var bar=hits.stream().filter(h->h.icon().equals("army_scrollbar")).findFirst().orElseThrow(()->new AssertionError("Overflowing air wing list needs the native scrollbar"));if(!CommanderHud.pressAt(bar.x()+bar.w()/2.,bar.y()+1,InputConstants.MOUSE_BUTTON_LEFT,false)||!CommanderHud.dragAt(bar.x(),bar.y()+bar.h())||!CommanderHud.releaseAt(bar.x(),InputConstants.MOUSE_BUTTON_LEFT))throw new AssertionError("Air wing scrollbar must drag to the end");});
        game.waitTicks(2);
        game.runOnClient(client->{if(CommanderPanels.hits().stream().noneMatch(h->h.tip().startsWith("\u00a7e"+last.name()+"\u00a7r")))throw new AssertionError("Scrollbar end must reveal the last air wing");});
        game.takeScreenshot("hoi-air-wing-scroll-end-1280x720-gui2");
    }
    private static void wingControls(ClientGameTestContext game,int[] size,List<Open> requests){var view=new View[1];game.runOnClient(client->{view[0]=new View("KOR",client.level.dimension().identifier().toString(),Mode.AIR,List.of(),List.of(wing("a","base-a",250,400),wing("b","base-b",500,400),wing("c","base-a",250,400)));CommanderHud.accept(view[0]);CommanderPanels.showWings(List.of("a","b","c"));});game.waitTicks(2);game.runOnClient(client->{var time=CommanderPanels.hits().stream().filter(h->h.icon().equals("strategicair_day_night")&&h.tip().startsWith("c\n")).findFirst().orElseThrow();var commands=new ArrayList<CommanderOrderPayloads.Command>();CommanderOrders.selectionObserver=q->{};CommanderOrders.commandObserver=commands::add;try{CommanderOrders.accept(new CommanderOrderPayloads.Context(java.util.UUID.randomUUID().toString(),0,"KOR",client.level.dimension().identifier().toString(),""));click(time);}finally{CommanderOrders.reset();CommanderOrders.commandObserver=null;CommanderOrders.selectionObserver=null;}if(commands.size()!=1||!commands.getFirst().action().equals("AIR_SETTING/SORTIE_NEXT")||!commands.getFirst().selection().equals(List.of("c","sortie/BOTH"))||!requests.isEmpty())throw new AssertionError("Sortie button must directly cycle exactly one wing: "+commands+" "+requests);var ace=CommanderPanels.hits().stream().filter(h->h.icon().equals("ace_none")).findFirst().orElseThrow();click(ace);if(requests.size()!=1||requests.getFirst().mode()!=Mode.AIR_REINFORCEMENT||!requests.getFirst().target().equals("aces")||requests.getFirst().selection().size()!=1||!Set.of("a","b","c").contains(requests.getFirst().selection().getFirst()))throw new AssertionError("Ace button must open its actual wing roster only");requests.clear();var policy=CommanderPanels.hits().stream().filter(h->h.icon().equals("wing_prio_strip")&&h.tip().startsWith("c\n")).findFirst().orElseThrow();click(policy);if(!requests.equals(List.of(new Open(Mode.AIR_REINFORCEMENT,"policy",List.of("c")))))throw new AssertionError("Policy button must scope exactly one wing");requests.clear();var info=CommanderPanels.hits().stream().filter(h->h.icon().equals("unitlist_unitinfo_button")&&h.tip().equals("picture-c")).findFirst().orElseThrow();var carrier=CommanderPanels.hits().stream().filter(h->h.icon().equals("airwing_carrier_icon")).toList();if(carrier.size()!=1||!carrier.getFirst().tip().equals("carrier-c")||!CommanderPanels.tooltipAt(carrier.getFirst().x()+carrier.getFirst().w()/2.,carrier.getFirst().y()+carrier.getFirst().h()/2.).equals("carrier-c")||!CommanderPanels.tooltipAt(info.x()+2,info.y()+2).equals("picture-c"))throw new AssertionError("The plane picture and the carrier icon must show their own original tooltips: "+carrier);var details=new ArrayList<CommanderAirWingPayloads.Request>();CommanderAirWingHud.requestObserver=details::add;try{click(info);if(!requests.isEmpty()||details.size()!=1||!details.getFirst().wing().equals("c")||CommanderAirWingHud.window()==null||!CommanderAirWingHud.window().wing().equals("c"))throw new AssertionError("Equipment portrait must open its actual wing details window: "+details+" "+requests);CommanderAirWingHud.reset();}finally{CommanderAirWingHud.requestObserver=null;}if(CommanderPanels.hits().stream().noneMatch(h->h.tip().startsWith("국가 연료")))throw new AssertionError("Native base fuel icon must expose authoritative country fuel");var close=CommanderPanels.hits().stream().filter(h->h.icon().equals("air_wing_close/a")).findFirst().orElseThrow();click(close);if(!Set.copyOf(CommanderPanels.commandSelection()).equals(Set.of("air/b","air/c"))||!requests.isEmpty())throw new AssertionError("Wing close must preserve same-base sibling and other-base selection");CommanderHud.accept(view[0]);});game.waitTicks(2);game.runOnClient(client->{if(!Set.copyOf(CommanderPanels.commandSelection()).equals(Set.of("air/b","air/c")))throw new AssertionError("Individual wing deselection did not survive refresh");});game.takeScreenshot("hoi-air-wing-controls-and-scoped-close-"+size[0]+"x"+size[1]+"-gui"+size[2]);}
    private static void baseTooltip(ClientGameTestContext game,int[] size,List<Open> requests){
        var hover=new int[2];var expected=new String[1];game.runOnClient(client->{var hit=CommanderPanels.hits().stream().filter(h->h.tip().contains("§H150§!")&&h.tip().contains("§H250§!")).findFirst().orElseThrow();expected[0]=hit.tip();double scale=client.getWindow().getGuiScale();hover[0]=(int)Math.round((hit.x()+hit.w()/2.)*scale);hover[1]=(int)Math.round((hit.y()+hit.h()/2.)*scale);if(!expected[0].contains("\n\n")||expected[0].contains("$"))throw new AssertionError("Native base tooltip paragraphs and complete authoritative substitutions required");});
        game.getInput().setCursorPos(hover[0],hover[1]);game.waitTicks(16);game.runOnClient(client->{if(!CommanderHud.renderedTooltip().equals(expected[0])||!requests.isEmpty())throw new AssertionError("Base capacity hover must render current native text without issuing requests");var bounds=CommanderHud.tooltipBounds();if(bounds==null||bounds.x()<0||bounds.y()<0||bounds.x()+bounds.width()>client.getWindow().getGuiScaledWidth()||bounds.y()+bounds.height()>client.getWindow().getGuiScaledHeight())throw new AssertionError("Base capacity tooltip escaped viewport");});game.takeScreenshot("hoi-air-base-capacity-native-tooltip-"+size[0]+"x"+size[1]+"-gui"+size[2]);game.getInput().setCursorPos(size[0]-30,90);game.waitTicks(1);
    }
    private static void listPanel(ClientGameTestContext game,java.nio.file.Path shot){
        int[] probe=game.computeOnClient(client->{var header=CommanderPanels.hits().stream().filter(h->h.tip().contains("§H150§!")&&h.tip().contains("§H250§!")).max(Comparator.comparingInt(CommanderPanels.Hit::w)).orElseThrow();double scale=client.getWindow().getGuiScale();return new int[]{(int)Math.round((header.x()+header.w())*scale)+6,(int)Math.round((header.y()+header.h()/2.)*scale)};});
        try{int rgb=javax.imageio.ImageIO.read(shot.toFile()).getRGB(probe[0],probe[1]);if(Math.max(rgb>>16&255,Math.max(rgb>>8&255,rgb&255))>45)throw new AssertionError("The native black list panel must sit behind the air base and wing rows: "+Integer.toHexString(rgb));}catch(java.io.IOException error){throw new AssertionError(error);}
    }
    private static CommanderPanels.Hit mission(String key){String name=UiCommandLabels.text(key,"");return CommanderPanels.hits().stream().filter(h->h.tip().startsWith(name+"\n")).findFirst().orElseThrow();}
    private static void click(CommanderPanels.Hit hit){var screen=net.minecraft.client.Minecraft.getInstance().gui.screen();var event=new MouseButtonEvent(hit.x()+hit.w()/2.,hit.y()+hit.h()/2.,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0));if(!screen.mouseClicked(event,false))throw new AssertionError("Air panel click leaked to the map");screen.mouseReleased(event);}
}
